package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Splits the import into its lines (blank lines skipped) and checks each with the person form's own
 *  rules; a name or contact repeated within the import, or an import with no lines, is refused. */
public class ValidateImport {
    public void validate(@RequestBody ImportRequest request, Out<ImportLines> lines)
            throws InvalidPersonException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<PersonRequest> checked = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        for (String line : text.split("\\r?\\n")) {
            if (line.isBlank()) continue;
            String[] f = line.split(",", 4);
            PersonRequest person = PersonForm.check(new PersonRequest(f[0], f.length > 1 ? f[1] : "", null,
                    f.length > 2 ? f[2] : "", null, f.length > 3 ? f[3] : "", null));
            if (!names.add(person.name().toLowerCase(Locale.ROOT))) {
                throw new InvalidPersonException("The name is repeated in the import: " + person.name());
            }
            if (person.contact() != null && !contacts.add(person.contact())) {
                throw new InvalidPersonException("The contact is repeated in the import: " + person.contact());
            }
            checked.add(person);
        }
        if (checked.isEmpty()) {
            throw new InvalidPersonException("Import at least one line of name,grade,terms,contact");
        }
        lines.set(new ImportLines(checked));
    }
}
# POST /api/sheets/{sheetId}/import-openings — add each pasted line of name,period,amount to the
# person's opening balance for the period (so to their carried figure for it). Every line is checked
# first: a person not on the sheet by name or alias, a period not on the sheet, or an amount that is not
# 0.00 or more with two decimals refuses the whole paste and nothing is written.
# Responds with how many lines went through.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.period.ValidateImportOpenings
  next: import
import:
  class: net.officefloor.hq.app.period.ImportOpenings
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithImportOpenings
# POST /api/sheets/{sheetId}/import-people — per pasted line of name,grade,terms,contact, in order,
# update the person whose name or alias it names (as the form edits them) or else add a person. Every
# line is checked first by the person form's rules (a name, contact or person repeated within the import
# is refused too): when any line is refused nothing is imported. Responds with how many were added and
# how many updated.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateImport
  next: create
create:
  class: net.officefloor.hq.app.person.ImportPeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithImport
# POST /api/sheets/{sheetId}/import-rates — set a rate per pasted line of grade,rate,from,to, in order,
# each as the rate form sets it. Every line is checked first by the rate form's rules: when any line
# is refused nothing is set. Responds with how many were set.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.rate.ValidateImportRates
  next: import
import:
  class: net.officefloor.hq.app.rate.ImportRates
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithImportRates

